-- Additional GNS3 benchmark examples for the existing MPLS-core lab.
-- Inspired by general fault categories (link, routing, forwarding, addressing),
-- NOT copied from or executed by NIKA. Requires matching GNS3 topology/config.
-- The cases are declarative only: no device changes occur during seeding.
-- Idempotent: existing scenario_key entries and user edits are preserved.
-- Uses nullable attribution so it works on databases without the demo admin.
BEGIN;

INSERT INTO benchmark_scenarios (
    id, scenario_key, version, name, description, topology, initial_message,
    definition, created_by, last_updated_by
)
VALUES
    -- Link & Interface: pe1-fa1-0-core-link-down
    ('benc-031126-30000001', 'pe1-fa1-0-core-link-down', '1.0', 'PE1 FastEthernet1/0 administrative link-down', 'Mất liên kết lõi P1–PE1; shutdown có chủ đích trên PE1 FastEthernet1/0.', 'mpls-core', 'Chẩn đoán nguyên nhân đường kết nối qua PE1 FastEthernet1/0 bị gián đoạn. Chỉ thu thập bằng chứng, không thay đổi cấu hình.', '{"preconditions":[{"device":"PE1","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"FastEthernet1/0 is up, line protocol is up"}}],"injection":[{"device":"PE1","action":"interface_shutdown","interface":"FastEthernet1/0"}],"fault_verification":[{"device":"PE1","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"administratively down"}}],"ground_truth":[{"fault_type":"link_down","device":"PE1","interface":"FastEthernet1/0"}],"evaluation_required_terms":["PE1","FastEthernet1/0","down"],"cleanup":[{"device":"PE1","action":"interface_no_shutdown","interface":"FastEthernet1/0"}]}'::jsonb, NULL, NULL),
    -- Link & Interface: pe2-fa1-0-core-link-down
    ('benc-031126-30000002', 'pe2-fa1-0-core-link-down', '1.0', 'PE2 FastEthernet1/0 administrative link-down', 'Mất liên kết lõi P2–PE2; shutdown có chủ đích trên PE2 FastEthernet1/0.', 'mpls-core', 'Chẩn đoán nguyên nhân đường kết nối qua PE2 FastEthernet1/0 bị gián đoạn. Chỉ thu thập bằng chứng, không thay đổi cấu hình.', '{"preconditions":[{"device":"PE2","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"FastEthernet1/0 is up, line protocol is up"}}],"injection":[{"device":"PE2","action":"interface_shutdown","interface":"FastEthernet1/0"}],"fault_verification":[{"device":"PE2","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"administratively down"}}],"ground_truth":[{"fault_type":"link_down","device":"PE2","interface":"FastEthernet1/0"}],"evaluation_required_terms":["PE2","FastEthernet1/0","down"],"cleanup":[{"device":"PE2","action":"interface_no_shutdown","interface":"FastEthernet1/0"}]}'::jsonb, NULL, NULL),
    -- Link & Interface: ce-1b-fa0-0-uplink-down
    ('benc-031126-30000003', 'ce-1b-fa0-0-uplink-down', '1.0', 'CE-1B FastEthernet0/0 administrative link-down', 'Mất kết nối uplink CE–PE tại site CUS_B; shutdown có chủ đích trên CE-1B FastEthernet0/0.', 'mpls-core', 'Chẩn đoán nguyên nhân đường kết nối qua CE-1B FastEthernet0/0 bị gián đoạn. Chỉ thu thập bằng chứng, không thay đổi cấu hình.', '{"preconditions":[{"device":"CE-1B","command":"show interfaces FastEthernet0/0 | include line protocol","assertion":{"contains":"FastEthernet0/0 is up, line protocol is up"}}],"injection":[{"device":"CE-1B","action":"interface_shutdown","interface":"FastEthernet0/0"}],"fault_verification":[{"device":"CE-1B","command":"show interfaces FastEthernet0/0 | include line protocol","assertion":{"contains":"administratively down"}}],"ground_truth":[{"fault_type":"link_down","device":"CE-1B","interface":"FastEthernet0/0"}],"evaluation_required_terms":["CE-1B","FastEthernet0/0","down"],"cleanup":[{"device":"CE-1B","action":"interface_no_shutdown","interface":"FastEthernet0/0"}]}'::jsonb, NULL, NULL),
    -- Link & Interface: ce-2a-fa0-0-uplink-down
    ('benc-031126-30000004', 'ce-2a-fa0-0-uplink-down', '1.0', 'CE-2A FastEthernet0/0 administrative link-down', 'Mất kết nối uplink CE–PE tại site CUS_A; shutdown có chủ đích trên CE-2A FastEthernet0/0.', 'mpls-core', 'Chẩn đoán nguyên nhân đường kết nối qua CE-2A FastEthernet0/0 bị gián đoạn. Chỉ thu thập bằng chứng, không thay đổi cấu hình.', '{"preconditions":[{"device":"CE-2A","command":"show interfaces FastEthernet0/0 | include line protocol","assertion":{"contains":"FastEthernet0/0 is up, line protocol is up"}}],"injection":[{"device":"CE-2A","action":"interface_shutdown","interface":"FastEthernet0/0"}],"fault_verification":[{"device":"CE-2A","command":"show interfaces FastEthernet0/0 | include line protocol","assertion":{"contains":"administratively down"}}],"ground_truth":[{"fault_type":"link_down","device":"CE-2A","interface":"FastEthernet0/0"}],"evaluation_required_terms":["CE-2A","FastEthernet0/0","down"],"cleanup":[{"device":"CE-2A","action":"interface_no_shutdown","interface":"FastEthernet0/0"}]}'::jsonb, NULL, NULL),
    -- Layer 2 / Link: switch1-fa1-0-trunk-down
    ('benc-031126-30000005', 'switch1-fa1-0-trunk-down', '1.0', 'Switch1 FastEthernet1/0 administrative link-down', 'Tắt cổng trunk nối mạng LAN của CE-1A; shutdown có chủ đích trên Switch1 FastEthernet1/0.', 'mpls-core', 'Chẩn đoán nguyên nhân đường kết nối qua Switch1 FastEthernet1/0 bị gián đoạn. Chỉ thu thập bằng chứng, không thay đổi cấu hình.', '{"preconditions":[{"device":"Switch1","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"FastEthernet1/0 is up, line protocol is up"}}],"injection":[{"device":"Switch1","action":"interface_shutdown","interface":"FastEthernet1/0"}],"fault_verification":[{"device":"Switch1","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"administratively down"}}],"ground_truth":[{"fault_type":"link_down","device":"Switch1","interface":"FastEthernet1/0"}],"evaluation_required_terms":["Switch1","FastEthernet1/0","down"],"cleanup":[{"device":"Switch1","action":"interface_no_shutdown","interface":"FastEthernet1/0"}]}'::jsonb, NULL, NULL),
    -- Layer 2 / Link: switch3-fa1-0-trunk-down
    ('benc-031126-30000006', 'switch3-fa1-0-trunk-down', '1.0', 'Switch3 FastEthernet1/0 administrative link-down', 'Tắt cổng trunk nối mạng LAN của CE-2A; shutdown có chủ đích trên Switch3 FastEthernet1/0.', 'mpls-core', 'Chẩn đoán nguyên nhân đường kết nối qua Switch3 FastEthernet1/0 bị gián đoạn. Chỉ thu thập bằng chứng, không thay đổi cấu hình.', '{"preconditions":[{"device":"Switch3","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"FastEthernet1/0 is up, line protocol is up"}}],"injection":[{"device":"Switch3","action":"interface_shutdown","interface":"FastEthernet1/0"}],"fault_verification":[{"device":"Switch3","command":"show interfaces FastEthernet1/0 | include line protocol","assertion":{"contains":"administratively down"}}],"ground_truth":[{"fault_type":"link_down","device":"Switch3","interface":"FastEthernet1/0"}],"evaluation_required_terms":["Switch3","FastEthernet1/0","down"],"cleanup":[{"device":"Switch3","action":"interface_no_shutdown","interface":"FastEthernet1/0"}]}'::jsonb, NULL, NULL),
    -- Routing / OSPF: pe1-ospf-network-missing
    ('benc-031126-30000007', 'pe1-ospf-network-missing', '1.0', 'PE1 missing OSPF backbone statement', 'Xóa network statement OSPF backbone của PE1.', 'mpls-core', 'Chẩn đoán vì sao PE1 không còn tham gia OSPF backbone. Chỉ thu thập bằng chứng.', '{"preconditions":[{"device":"PE1","command":"show running-config | section router ospf","assertion":{"contains":"network 10.0.0.0 0.255.255.255 area 0"}}],"injection":[{"device":"PE1","action":"ospf_network_remove","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":0}],"fault_verification":[{"device":"PE1","command":"show running-config | section router ospf","assertion":{"not_contains":"network 10.0.0.0 0.255.255.255 area 0"}}],"ground_truth":[{"fault_type":"ospf_network_missing","device":"PE1"}],"evaluation_required_terms":["PE1","OSPF","network"],"cleanup":[{"device":"PE1","action":"ospf_network_add","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":0}]}'::jsonb, NULL, NULL),
    -- Routing / OSPF: pe2-ospf-network-missing
    ('benc-031126-30000008', 'pe2-ospf-network-missing', '1.0', 'PE2 missing OSPF backbone statement', 'Xóa network statement OSPF backbone của PE2.', 'mpls-core', 'Chẩn đoán vì sao PE2 không còn tham gia OSPF backbone. Chỉ thu thập bằng chứng.', '{"preconditions":[{"device":"PE2","command":"show running-config | section router ospf","assertion":{"contains":"network 10.0.0.0 0.255.255.255 area 0"}}],"injection":[{"device":"PE2","action":"ospf_network_remove","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":0}],"fault_verification":[{"device":"PE2","command":"show running-config | section router ospf","assertion":{"not_contains":"network 10.0.0.0 0.255.255.255 area 0"}}],"ground_truth":[{"fault_type":"ospf_network_missing","device":"PE2"}],"evaluation_required_terms":["PE2","OSPF","network"],"cleanup":[{"device":"PE2","action":"ospf_network_add","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":0}]}'::jsonb, NULL, NULL),
    -- Routing / OSPF: p2-ospf-backbone-area-mismatch
    ('benc-031126-30000009', 'p2-ospf-backbone-area-mismatch', '1.0', 'P2 OSPF backbone area mismatch', 'Chuyển toàn bộ network statement backbone OSPF của P2 từ area 0 sang area 1.', 'mpls-core', 'Chẩn đoán nguyên nhân neighbor OSPF giữa P2 và các thiết bị backbone không hình thành. Không khắc phục.', '{"preconditions":[{"device":"P2","command":"show running-config | section router ospf","assertion":{"contains":"network 10.0.0.0 0.255.255.255 area 0"}}],"injection":[{"device":"P2","action":"ospf_network_remove","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":0},{"device":"P2","action":"ospf_network_add","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":1}],"fault_verification":[{"device":"P2","command":"show running-config | section router ospf","assertion":{"contains":"network 10.0.0.0 0.255.255.255 area 1"}},{"device":"P2","command":"show running-config | section router ospf","assertion":{"not_contains":"network 10.0.0.0 0.255.255.255 area 0"}}],"ground_truth":[{"fault_type":"ospf_area_mismatch","device":"P2"}],"evaluation_required_terms":["P2","OSPF","area"],"cleanup":[{"device":"P2","action":"ospf_network_remove","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":1},{"device":"P2","action":"ospf_network_add","process_id":1,"network":"10.0.0.0","wildcard":"0.255.255.255","area":0}]}'::jsonb, NULL, NULL),
    -- MPLS / Forwarding: pe1-fa2-0-mpls-disabled
    ('benc-031126-3000000a', 'pe1-fa2-0-mpls-disabled', '1.0', 'PE1 FastEthernet2/0 MPLS disabled', 'Gỡ mpls ip khỏi interface core FastEthernet2/0 của PE1.', 'mpls-core', 'Chẩn đoán vì sao LDP/MPLS không hoạt động trên PE1 FastEthernet2/0. Không cấu hình lại thiết bị.', '{"preconditions":[{"device":"PE1","command":"show running-config interface FastEthernet2/0 | include mpls ip","assertion":{"contains":"mpls ip"}}],"injection":[{"device":"PE1","action":"mpls_disable","interface":"FastEthernet2/0"}],"fault_verification":[{"device":"PE1","command":"show running-config interface FastEthernet2/0 | include mpls ip","assertion":{"not_contains":"mpls ip"}}],"ground_truth":[{"fault_type":"mpls_disabled","device":"PE1","interface":"FastEthernet2/0"}],"evaluation_required_terms":["PE1","FastEthernet2/0","MPLS"],"cleanup":[{"device":"PE1","action":"mpls_enable","interface":"FastEthernet2/0"}]}'::jsonb, NULL, NULL),
    -- MPLS / Forwarding: pe2-fa2-0-mpls-disabled
    ('benc-031126-3000000b', 'pe2-fa2-0-mpls-disabled', '1.0', 'PE2 FastEthernet2/0 MPLS disabled', 'Gỡ mpls ip khỏi interface core FastEthernet2/0 của PE2.', 'mpls-core', 'Chẩn đoán vì sao LDP/MPLS không hoạt động trên PE2 FastEthernet2/0. Không cấu hình lại thiết bị.', '{"preconditions":[{"device":"PE2","command":"show running-config interface FastEthernet2/0 | include mpls ip","assertion":{"contains":"mpls ip"}}],"injection":[{"device":"PE2","action":"mpls_disable","interface":"FastEthernet2/0"}],"fault_verification":[{"device":"PE2","command":"show running-config interface FastEthernet2/0 | include mpls ip","assertion":{"not_contains":"mpls ip"}}],"ground_truth":[{"fault_type":"mpls_disabled","device":"PE2","interface":"FastEthernet2/0"}],"evaluation_required_terms":["PE2","FastEthernet2/0","MPLS"],"cleanup":[{"device":"PE2","action":"mpls_enable","interface":"FastEthernet2/0"}]}'::jsonb, NULL, NULL),
    -- MPLS / Forwarding: p1-fa1-0-mpls-disabled
    ('benc-031126-3000000c', 'p1-fa1-0-mpls-disabled', '1.0', 'P1 FastEthernet1/0 MPLS disabled', 'Gỡ mpls ip khỏi interface core FastEthernet1/0 của P1.', 'mpls-core', 'Chẩn đoán vì sao LDP/MPLS không hoạt động trên P1 FastEthernet1/0. Không cấu hình lại thiết bị.', '{"preconditions":[{"device":"P1","command":"show running-config interface FastEthernet1/0 | include mpls ip","assertion":{"contains":"mpls ip"}}],"injection":[{"device":"P1","action":"mpls_disable","interface":"FastEthernet1/0"}],"fault_verification":[{"device":"P1","command":"show running-config interface FastEthernet1/0 | include mpls ip","assertion":{"not_contains":"mpls ip"}}],"ground_truth":[{"fault_type":"mpls_disabled","device":"P1","interface":"FastEthernet1/0"}],"evaluation_required_terms":["P1","FastEthernet1/0","MPLS"],"cleanup":[{"device":"P1","action":"mpls_enable","interface":"FastEthernet1/0"}]}'::jsonb, NULL, NULL),
    -- Addressing / IPv4: ce-1b-uplink-wrong-ip
    ('benc-031126-3000000d', 'ce-1b-uplink-wrong-ip', '1.0', 'CE-1B incorrect uplink IPv4 address', 'Gán sai IPv4 192.168.22.2 thay vì 192.168.2.2 cho FastEthernet0/0 trên CE-1B.', 'mpls-core', 'Chẩn đoán vì sao CE-1B không còn trao đổi lưu lượng đúng qua FastEthernet0/0. Chỉ thu thập bằng chứng.', '{"preconditions":[{"device":"CE-1B","command":"show running-config interface FastEthernet0/0 | include ip address","assertion":{"contains":"ip address 192.168.2.2 255.255.255.0"}}],"injection":[{"device":"CE-1B","action":"interface_ip_set","interface":"FastEthernet0/0","ip_address":"192.168.22.2","subnet_mask":"255.255.255.0"}],"fault_verification":[{"device":"CE-1B","command":"show running-config interface FastEthernet0/0 | include ip address","assertion":{"contains":"ip address 192.168.22.2 255.255.255.0"}}],"ground_truth":[{"fault_type":"wrong_ip_address","device":"CE-1B","interface":"FastEthernet0/0"}],"evaluation_required_terms":["CE-1B","FastEthernet0/0","IP address"],"cleanup":[{"device":"CE-1B","action":"interface_ip_set","interface":"FastEthernet0/0","ip_address":"192.168.2.2","subnet_mask":"255.255.255.0"}]}'::jsonb, NULL, NULL),
    -- Addressing / IPv4: ce-2b-uplink-wrong-ip
    ('benc-031126-3000000e', 'ce-2b-uplink-wrong-ip', '1.0', 'CE-2B incorrect uplink IPv4 address', 'Gán sai IPv4 192.168.44.2 thay vì 192.168.4.2 cho FastEthernet0/0 trên CE-2B.', 'mpls-core', 'Chẩn đoán vì sao CE-2B không còn trao đổi lưu lượng đúng qua FastEthernet0/0. Chỉ thu thập bằng chứng.', '{"preconditions":[{"device":"CE-2B","command":"show running-config interface FastEthernet0/0 | include ip address","assertion":{"contains":"ip address 192.168.4.2 255.255.255.0"}}],"injection":[{"device":"CE-2B","action":"interface_ip_set","interface":"FastEthernet0/0","ip_address":"192.168.44.2","subnet_mask":"255.255.255.0"}],"fault_verification":[{"device":"CE-2B","command":"show running-config interface FastEthernet0/0 | include ip address","assertion":{"contains":"ip address 192.168.44.2 255.255.255.0"}}],"ground_truth":[{"fault_type":"wrong_ip_address","device":"CE-2B","interface":"FastEthernet0/0"}],"evaluation_required_terms":["CE-2B","FastEthernet0/0","IP address"],"cleanup":[{"device":"CE-2B","action":"interface_ip_set","interface":"FastEthernet0/0","ip_address":"192.168.4.2","subnet_mask":"255.255.255.0"}]}'::jsonb, NULL, NULL),
    -- Forwarding / ACL: pe1-cus-b-acl-102-block
    ('benc-031126-3000000f', 'pe1-cus-b-acl-102-block', '1.0', 'PE1 customer traffic blocked by ACL 102', 'Chèn ACL 102 vào FastEthernet4/0 để chặn mạng 172.16.2.0 tại CUS_B.', 'mpls-core', 'Chẩn đoán lý do traffic của 172.16.2.0 bị chặn tại PE1. Không khắc phục.', '{"preconditions":[{"device":"PE1","command":"show running-config interface FastEthernet4/0 | include access-group","assertion":{"not_contains":"ip access-group 102 in"}},{"device":"PE1","command":"show running-config | include ^access-list 102","assertion":{"not_contains":"access-list 102"}}],"injection":[{"device":"PE1","action":"acl_block","interface":"FastEthernet4/0","acl_number":102,"direction":"in","source_network":"172.16.2.0","source_wildcard":"0.0.0.255"}],"fault_verification":[{"device":"PE1","command":"show running-config interface FastEthernet4/0 | include access-group","assertion":{"contains":"ip access-group 102 in"}}],"ground_truth":[{"fault_type":"acl_traffic_block","device":"PE1","interface":"FastEthernet4/0"}],"evaluation_required_terms":["PE1","ACL 102","172.16.2.0"],"cleanup":[{"device":"PE1","action":"acl_remove","interface":"FastEthernet4/0","acl_number":102,"direction":"in"}]}'::jsonb, NULL, NULL),
    -- Forwarding / ACL: pe2-cus-a-acl-103-block
    ('benc-031126-30000010', 'pe2-cus-a-acl-103-block', '1.0', 'PE2 customer traffic blocked by ACL 103', 'Chèn ACL 103 vào FastEthernet3/0 để chặn mạng 172.16.3.0 tại CUS_A.', 'mpls-core', 'Chẩn đoán lý do traffic của 172.16.3.0 bị chặn tại PE2. Không khắc phục.', '{"preconditions":[{"device":"PE2","command":"show running-config interface FastEthernet3/0 | include access-group","assertion":{"not_contains":"ip access-group 103 in"}},{"device":"PE2","command":"show running-config | include ^access-list 103","assertion":{"not_contains":"access-list 103"}}],"injection":[{"device":"PE2","action":"acl_block","interface":"FastEthernet3/0","acl_number":103,"direction":"in","source_network":"172.16.3.0","source_wildcard":"0.0.0.255"}],"fault_verification":[{"device":"PE2","command":"show running-config interface FastEthernet3/0 | include access-group","assertion":{"contains":"ip access-group 103 in"}}],"ground_truth":[{"fault_type":"acl_traffic_block","device":"PE2","interface":"FastEthernet3/0"}],"evaluation_required_terms":["PE2","ACL 103","172.16.3.0"],"cleanup":[{"device":"PE2","action":"acl_remove","interface":"FastEthernet3/0","acl_number":103,"direction":"in"}]}'::jsonb, NULL, NULL),
    -- Addressing / Loopback: p1-loopback0-admin-down
    ('benc-031126-30000011', 'p1-loopback0-admin-down', '1.0', 'P1 Loopback0 administratively down', 'Shutdown interface loopback P1 đang có địa chỉ 10.0.0.1/32.', 'mpls-core', 'Chẩn đoán vì sao Loopback0 của P1 không còn hoạt động. Không khắc phục.', '{"preconditions":[{"device":"P1","command":"show interfaces Loopback0 | include line protocol","assertion":{"contains":"Loopback0 is up, line protocol is up"}}],"injection":[{"device":"P1","action":"interface_shutdown","interface":"Loopback0"}],"fault_verification":[{"device":"P1","command":"show interfaces Loopback0 | include line protocol","assertion":{"contains":"administratively down"}}],"ground_truth":[{"fault_type":"loopback_admin_down","device":"P1","interface":"Loopback0"}],"evaluation_required_terms":["P1","Loopback0","down"],"cleanup":[{"device":"P1","action":"interface_no_shutdown","interface":"Loopback0"}]}'::jsonb, NULL, NULL)
ON CONFLICT (scenario_key) DO NOTHING;

COMMIT;
